harness.example:
// server: /hitch puts the player's horse in front of the empty cart beside them
const { Cart } = kcds.world;
const { Horse } = kcds.characters;
const yard = Cart.spawn('cart_b', new kcds.math.Vector3(2675, 1560, 30), undefined, undefined, {
  harnessed: false,
});

kcds.core.Events.on('playerCommand', (player, command) => {
  if (command !== 'hitch') {
    return;
  }
  const horse = Horse.all().find((h) => h.ownerId === player.id);
  if (!horse || !yard.harness(horse)) {
    kcds.core.Chat.sendToPlayer(player, 'Bring your horse to the cart first.');
  }
});

harness.exampleCs:
// server: /hitch puts the player's horse in front of the empty cart beside them
var yard = Cart.Spawn("cart_b", new Vector3(2675, 1560, 30), Sdk.Undefined, Sdk.Undefined, new { harnessed = false });

Events.On("playerCommand", (Player player, string command) =>
{
    if (command != "hitch")
    {
        return;
    }
    var horse = Horse.All().FirstOrDefault(h => h.OwnerId == player.Id);
    if (horse == null || !yard.Harness(horse))
    {
        Chat.SendToPlayer(player, "Bring your horse to the cart first.");
    }
});

